  "excludes.advisoryImmichDb": "Az Immich minden fénykép albumait, arcait és dátumait egy PostgreSQL adatbázisban tartja, amely egy teljesen külön konténerben fut, így ez a biztonsági mentés nem tartalmazza. Az innen való visszaállítás visszahozza a képeket, csak mindezek nélkül. A BombVault annak az adatbázisnak a konténeréről magától készít dumpot, amikor azt menti, ezért ellenőrizd, hogy benne van-e az ütemezésedben.",
