  "settings.ownOffsiteRetentionHint": "Egy forrás a távoli repójában lévő biztonsági mentéseket a fenti közös távoli szabályok helyett saját szabályok szerint is megtarthatja. A saját szabályok nélküli forrás a közöseket használja.",
  "settings.ownOffsiteRetentionToggleHint": "Be: a forrás távoli repója az alábbi öt szabály szerint tartja meg a biztonsági mentéseit, amelyek a közös távoli értékekből indulnak. Ki: a közös távoli szabályokat használja. Minden 0 esetén a forrás minden távoli mentése megmarad.",
  "settings.retentionExtraTargets": "A további külső célok a saját szabályaikat követik, ezeket minden szakasz Telephelyen kívüli másolat kártyáján állítod be.",
  "settings.retentionOffsiteScope": "Ezek a szabályok minden szakasz elsődleges külső céljára vonatkoznak, vagyis a külső mezőjében megadott címre. Minden további külső cél, akár egy célból létrehozott is, megtartja a saját szabályait. Ha ott csak nullák vannak, a BombVault soha nem takarítja.",
  "settings.retentionCombineInfo": "Az öt szabály VAGY logikával kombinálódik: egy mentés megmarad, ha bármelyik szabály megőrizné. Nem adódnak össze egy rögzített számmá. Külön érvényes minden mentett elemre.",

  // Off-site (rclone)
  "rclone.title": "Külső helyszín (rclone)",
  "rclone.hint": "Illessz be egy rclone-konfigurációt a felhőbe biztonsági mentéshez (Backblaze B2, S3, Google Drive, …). Titkosítva tárolódik. Az SMB/NFS nem igényel rclone-t: csatold a megosztást az Unraidben, és állíts rá egy mentési útvonalat.",
  "rclone.configured": "Beállított távoli helyek",
  "rclone.pathHint": "Ezután állíts egy biztonsági mentési útvonalat „rclone:<remote>:<bucket>/path” értékre, hogy az adott szakaszt külső célra küldd.",
  "cloud.title": "Megosztott felhőbeli hitelesítő adatok (S3 / restic REST)",
  "cloud.hint": "Hitelesítő adatok távoli restic backendekhez, rclone nélkül. Mentés után állíts be egy biztonsági mentési útvonalat egy távoli repóra, pl. s3:s3.amazonaws.com/bucket/path, rest:http://host:8000/repo vagy sftp:user@host:/repo. A titkok titkosítva tárolódnak és többé nem jelennek meg.",
