  "cloud.credSets.title": "További hitelesítő adatkészletek",
  "cloud.credSets.hint": "Adj egy vagy több külső célnak saját S3 vagy restic REST hitelesítő adatokat, ahelyett hogy a fentieket osztanák meg.",
