  "recovery.abTitle": "Importálás az Appdata.Backup bővítményből",
  "recovery.abIntro": "Az Appdata.Backup bővítmény által írt archívumokból a megfelelő konténerek visszaállítási pontjait készíti, mindegyiket azzal a dátummal, amikor a bővítmény létrehozta. Az archívumokat csak olvassa, soha nem módosítja és nem törli. Mindegyiket a tároló mellé csomagolja ki, menti, majd a kicsomagolt másolatot ismét törli, ezért ott a legnagyobb archívumnak is el kell férnie.",
