  "mcp.setupOther": "Bármelyik kliens megfelel, amely Streamable HTTP-t beszél. Add meg ezeket ott, ahol távoli MCP-szervert kér, a kulccsal a két fejléc egyikében.",
  "mcp.setupWhere": "Hol van a fájl",
