  "mcp.setupChatGPT": "A ChatGPT-ben nyisd meg a Beállítások, Alkalmazások és csatolók részt, és a Speciális beállítások alatt kapcsold be a fejlesztői módot. Aztán válaszd a Létrehozás lehetőséget, adj nevet a csatolónak, illeszd be a csatoló URL-jét MCP-szerver URL-ként, válaszd az OAuth hitelesítést, erősítsd meg, hogy megbízol benne, és hozd létre.",
  "mcp.setupClaudeAi": "A claude.ai-on nyisd meg a Beállítások, Csatolók részt, és válaszd az Egyéni csatoló hozzáadása lehetőséget. Adj neki nevet, illeszd be a csatoló URL-jét, az OAuth kliensazonosítót és a titkot hagyd üresen, és add hozzá. Aztán válaszd a Csatlakozás lehetőséget.",
