  "receiver.server.title": "Fogadószerver",
  "receiver.server.tip": "Egy rest-server append-only módban ezen a gépen. A csoportod többi példánya ide másolhatja a külső mentéseit, és még az sem törölheti a megérkezettet, akinek megvan a bejelentkezésük.",
  "receiver.server.intro": "Engedd, hogy a partnereid ide másolják a külső mentéseiket. A BombVault itt elindít egy rest-servert append-only módban, és felkínálja a csoportod példányainak.",
  "receiver.server.setUp": "Fogadószerver beállítása",
