  "anomaly.sentence.newData": "A(z) {name} egyetlen biztonsági mentésben {bytes} új adatot tett hozzá. Szokásosan legfeljebb {typical} kerül hozzá.",
  "anomaly.sentence.newDataRewrite": "A(z) {name} egyetlen biztonsági mentésben {bytes} adatot írt újra, legalább a felét mindannak, amit ment ({source}). Ha nem változtattál ennyit, ellenőrizd, hogy a fájlokat nem titkosították vagy cserélték-e ki.",
  "anomaly.sentence.newDataRenamed": "A(z) {name} minden fájlja újnak tűnik, pedig van korábbi biztonsági mentés, és {source} méretből {bytes} újra tárolásra került. Az egyszerre átnevezett és újraírt fájlok a zsarolóvírusokra jellemzők. Mindenekelőtt ellenőrizd a fájlokat.",
  "anomaly.sentence.newDataFull": "A BombVault újra beolvasta a(z) {name} minden fájlját, mert egyetlen korábbi biztonsági mentés sem illeszkedett (új tároló, új mappák vagy megváltozott titkosítás). Tárolt új adat: {bytes}.",
